from hf_integration import HuggingFaceAPI, RevenueOptimizer
import requests

class BusinessContentGenerator:
    def __init__(self):
        self.hf_api = HuggingFaceAPI()
        self.optimizer = RevenueOptimizer()

        # Content templates for maximum efficiency
        self.templates = {
            'sales_email': {
                'prompt': "Write a compelling sales email for {industry} targeting {audience} about {product}. Focus on benefits and include a clear call-to-action:",
                'price': 0.25
            },
            'product_description': {
                'prompt': "Create an engaging product description for {product} in the {industry} industry. Highlight key features, benefits, and value proposition:",
                'price': 0.30
            },
