                'prompt': "Create persuasive marketing copy for {product} targeting {audience}. Focus on emotional triggers and benefits:",
                'price': 0.35
            },
            'business_proposal': {
                'prompt': "Write a business proposal for {service} targeting {client_type} in {industry}. Include problem, solution, and next steps:",
                'price': 0.60
            },
            'website_content': {
                'prompt': "Create website content for {page_type} page for a {industry} company. Make it SEO-friendly and conversion-focused:",
                'price': 0.45
            }
        }

        # Industry-specific optimizations
        self.industry_keywords = {
            'technology': ['innovative', 'cutting-edge', 'scalable', 'efficient', 'automated'],
            'healthcare': ['patient-focused', 'reliable', 'compliant', 'evidence-based', 'trusted'],
            'finance': ['secure', 'transparent', 'profitable', 'compliant', 'strategic'],
            'education': ['engaging', 'effective', 'accessible', 'comprehensive', 'proven'],
            'retail': ['quality', 'affordable', 'trendy', 'customer-focused', 'convenient'],
            'consulting': ['expert', 'results-driven', 'customized', 'strategic', 'experienced']
        }

    def generate_content(self, content_type, parameters, tier='basic'):
        """Generate business content with pricing"""

        if content_type not in self.templates:
            return {
                'success': False,
                'error': f"Content type '{content_type}' not supported",
                'available_types': list(self.templates.keys())
            }

        template = self.templates[content_type]

        try:
            # Format prompt with parameters
            prompt = template['prompt'].format(**parameters)

            # Add industry-specific keywords if available
            industry = parameters.get('industry', 'general')
            if industry in self.industry_keywords:
                keywords = ', '.join(self.industry_keywords[industry][:3])
                prompt += f" Use these key terms: {keywords}."

            # Generate content
            content = self.hf_api.generate_text(
                prompt, 
