            json.dump(self.revenue_data, f)

    def generate_api_key(self):
        """Generate a new API key"""
        timestamp = str(int(time.time()))
        random_string = os.urandom(16).hex()
        return hashlib.sha256((timestamp + random_string).encode()).hexdigest()[:32]

    def validate_api_key(self, api_key):
        """Validate and return API key info"""
        if api_key in self.api_keys:
            key_info = self.api_keys[api_key]
            if key_info.get('is_active', True):
                return key_info
        return None

    def check_rate_limit(self, api_key):
        """Check if request is within rate limits"""
        key_info = self.validate_api_key(api_key)
        if not key_info:
            return False

        tier = key_info['tier']
        limits = self.rate_limits[tier]

        now = datetime.now()
        hour_key = now.strftime('%Y-%m-%d-%H')
        day_key = now.strftime('%Y-%m-%d')

        # Initialize usage tracking for this key
        if api_key not in self.usage_stats:
            self.usage_stats[api_key] = {'hourly': {}, 'daily': {}}

        usage = self.usage_stats[api_key]

        # Check hourly limit
        hourly_count = usage['hourly'].get(hour_key, 0)
        if hourly_count >= limits['requests_per_hour']:
            return False

        # Check daily limit
        daily_count = usage['daily'].get(day_key, 0)
        if daily_count >= limits['requests_per_day']:
            return False

        return True

    def record_usage(self, api_key, cost=0.0):
        """Record API usage and revenue"""
        now = datetime.now()
        hour_key = now.strftime('%Y-%m-%d-%H')
        day_key = now.strftime('%Y-%m-%d')
        month_key = now.strftime('%Y-%m')

        # Update usage stats
        if api_key not in self.usage_stats:
            self.usage_stats[api_key] = {'hourly': {}, 'daily': {}}

        usage = self.usage_stats[api_key]
        usage['hourly'][hour_key] = usage['hourly'].get(hour_key, 0) + 1
        usage['daily'][day_key] = usage['daily'].get(day_key, 0) + 1

        # Update API key stats
        if api_key in self.api_keys:
            self.api_keys[api_key]['total_requests'] += 1
            self.api_keys[api_key]['total_spent'] += cost

        # Update revenue
        self.revenue_data['total_revenue'] += cost
        if 'monthly_revenue' not in self.revenue_data:
            self.revenue_data['monthly_revenue'] = {}
        self.revenue_data['monthly_revenue'][month_key] = self.revenue_data['monthly_revenue'].get(month_key, 0) + cost

        self.save_data()

