# Authentication decorator
def require_api_key(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        api_key = request.headers.get('X-API-Key') or request.args.get('api_key')

        if not api_key:
            return jsonify({'error': 'API key required', 'code': 401}), 401

        key_info = oasis_api.validate_api_key(api_key)
        if not key_info:
            return jsonify({'error': 'Invalid API key', 'code': 401}), 401

        if not oasis_api.check_rate_limit(api_key):
            return jsonify({'error': 'Rate limit exceeded', 'code': 429}), 429

        # Add key info to request context
        request.api_key = api_key
        request.key_info = key_info

        return f(*args, **kwargs)
    return decorated_function

