    def deploy_space(self, space_name, app_type, config, username=None):
        """Deploy a Hugging Face Space"""

        try:
            # Get template info
            template = self.space_templates.get(app_type)
            if not template:
                return {{"success": False, "error": "Invalid app type"}}

            # Create repository
            repo_id = f"{{username or 'oasis-ai'}}/{{space_name}}"

            try:
                create_repo(
                    repo_id=repo_id,
                    token=self.hf_token,
                    repo_type="space",
                    space_sdk=template['sdk']
                )
            except Exception as e:
                if "already exists" not in str(e):
                    return {{"success": False, "error": f"Failed to create repo: {{e}}"}}

            # Create temporary directory for files
            with tempfile.TemporaryDirectory() as temp_dir:

                # Generate app code
                if template['sdk'] == 'streamlit':
                    app_code = self.create_streamlit_app(app_type, config)
                    app_file = "app.py"
                else:
                    app_code = self.create_gradio_app(app_type, config)
                    app_file = "app.py"

                # Write app file
                app_path = os.path.join(temp_dir, app_file)
                with open(app_path, 'w') as f:
                    f.write(app_code)

                # Create requirements.txt
                if template['sdk'] == 'streamlit':
                    requirements = "streamlit\\nrequests"
                else:
                    requirements = "gradio\\nrequests"

                req_path = os.path.join(temp_dir, "requirements.txt")
                with open(req_path, 'w') as f:
                    f.write(requirements)

                # Create README.md
                readme_content = f"""---
title: {{config['title']}}
emoji: 🚀
colorFrom: blue
colorTo: green
sdk: {{template['sdk']}}
sdk_version: {"1.28.0" if template['sdk'] == 'streamlit' else "4.0.0"}
app_file: {{app_file}}
pinned: false
---

# {{config['title']}}

{{config['description']}}

Built with OASIS 2.0 Revolution - Ultra-lightweight AI content generation.

## Features
- Professional content generation
- Multiple content types
- Tier-based pricing
- Real-time API integration

## Usage
1. Select your content type
2. Fill in the parameters  
3. Choose quality tier
4. Generate content instantly

Powered by Hugging Face and OASIS AI.
"""

                readme_path = os.path.join(temp_dir, "README.md")
                with open(readme_path, 'w') as f:
                    f.write(readme_content)

                # Upload files
                for file_name in [app_file, "requirements.txt", "README.md"]:
                    file_path = os.path.join(temp_dir, file_name)
                    upload_file(
                        path_or_fileobj=file_path,
                        path_in_repo=file_name,
                        repo_id=repo_id,
                        token=self.hf_token,
                        repo_type="space"
                    )

            # Return deployment info
            space_url = f"https://huggingface.co/spaces/{{repo_id}}"

            return {{
                "success": True,
                "space_url": space_url,
                "repo_id": repo_id,
                "app_type": app_type,
                "sdk": template['sdk'],
                "deployment_cost": template['price'],
                "deployed_at": datetime.now().isoformat()
            }}

        except Exception as e:
            return {{
                "success": False,
                "error": str(e),
                "app_type": app_type
            }}

    def batch_deploy(self, deployments):
        """Deploy multiple spaces at once"""
        results = []
        total_cost = 0.0

        for deployment in deployments:
            result = self.deploy_space(
                deployment['space_name'],
                deployment['app_type'], 
                deployment['config'],
                deployment.get('username')
            )

            if result['success']:
                total_cost += result['deployment_cost']

            results.append(result)

        return {{
            "results": results,
            "total_deployments": len(deployments),
            "successful": len([r for r in results if r['success']]),
            "total_cost": total_cost,
            "batch_deployed_at": datetime.now().isoformat()
        }}

